    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}

    # Prefix sums let us score every possible rectangular patch efficiently.
    pref = {}
    for color in colors:
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )
        pref[color] = p

    best = [[None] * w for _ in range(h)]
    for color in colors:
        p = pref[color]
        for r1 in range(h):
            for r2 in range(r1 + 1, h + 1):
                for c1 in range(w):
