                        if area < 4:
                            continue
                        count = p[r2][c2] - p[r1][c2] - p[r2][c1] + p[r1][c1]
                        if count < 4 or count / area < 0.68:
                            continue
                        density = count / area
                        score = (density, area)
                        for r in range(r1, r2):
                            for c in range(c1, c2):
                                if best[r][c] is None or score > best[r][c][0]:
                                    best[r][c] = (score, color)

    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if best[r][c] is not None:
                out[r][c] = best[r][c][1]
    return out
